// Verify that the chemist delivers medicines offline
TestCase chemistOfflineDelivery {
    given Chemist has received Prescription
    when Chemist prepares delivery
    then Chemist should deliver Medicines offline
}

// Test Case 3: Lab Report Delivery and Update
// Verify that the lab delivers reports and updates the system
TestCase labReportDelivery {
    given Lab has received Prescription
    when Lab conducts tests
    then Lab should deliver Report and update System
}

// Test Case 4: Speciality Database Populated by Admin
// Verify that the speciality database is populated by Admin
TestCase specialityDatabasePopulated {
    given Admin has access to Speciality Database
    when Admin populates Database
    then Speciality Database should be populated
}

// Test Case 5: Doctor Database Linked to Specialities
