TestCase doctorDatabaseLinked {
    given Admin has access to Doctor Database
    when Admin links Specialities to Doctors
    then Doctor Database should be linked
}

// Test Case 6: Database Populated by Labs and Chemists
// Verify that labs and chemists populate their databases
TestCase databasePopulated {
    given Lab and Chemist have access to Database
    when Lab and Chemist populate Database
    then Database should be populated
}

// Test Case 7: Patient Registration
// Verify that the patient registers into the system
TestCase patientRegistration {
    given Patient has access to System
    when Patient registers
    then Patient should be registered
}
